(() => {
const outside=document.querySelector('#outside-view'),inside=document.querySelector('#inside-view'),dialog=document.querySelector('#document-dialog'),content=document.querySelector('#document-content'),title=document.querySelector('#document-title'),locationLabel=document.querySelector('#location'),motion=document.querySelector('#motion-toggle');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let room=false,transitioning=false,entryPromise=null,version=0,paused=reduced.matches,returnFocus=null;
function motionState(){window.portfolioMotionPlaying=!paused;document.body.classList.toggle('paused',paused);motion.textContent=paused?'Play':'Pause';motion.setAttribute('aria-label',paused?'Play animations':'Pause animations');motion.setAttribute('aria-pressed',String(paused));}
motionState();motion.addEventListener('click',()=>{paused=!paused;motionState();});reduced.addEventListener('change',e=>{paused=e.matches;motionState();});
function animateIn(){if(window.gsap&&!paused){gsap.fromTo(inside,{opacity:0},{opacity:1,duration:.7});gsap.fromTo('.room-frame',{scale:1.06,y:15},{scale:1,y:0,duration:1.1,ease:'power3.out'});}}
function showRoom(){outside.hidden=true;outside.inert=true;inside.hidden=false;inside.inert=false;document.body.dataset.view='inside';locationLabel.textContent='The study';room=true;transitioning=false;animateIn();}
function showOutside(){version++;transitioning=false;room=false;dialog.close();inside.hidden=true;inside.inert=true;outside.hidden=false;outside.inert=false;document.body.dataset.view='outside';locationLabel.textContent='Portfolio';window.cottageReset?.();window.resetDeskEnvelope?.();if(window.gsap){gsap.set('#outside-scene',{opacity:1});gsap.set('.outside-image',{clearProps:'transform,opacity'});}}
function enter(){if(room)return Promise.resolve();if(transitioning)return entryPromise;transitioning=true;document.body.dataset.view='entering';const id=++version;document.querySelectorAll('[data-enter],#enter-door').forEach(b=>b.disabled=true);
 entryPromise=(async()=>{try{if(window.cottageEnter&&!paused)await window.cottageEnter();else if(window.gsap&&!paused){await new Promise(resolve=>gsap.to('.outside-image',{scale:3.4,opacity:0,duration:1,transformOrigin:'41% 54%',ease:'power2.in',onComplete:resolve}));}}
 finally{document.querySelectorAll('[data-enter],#enter-door').forEach(b=>b.disabled=false);if(id===version)showRoom();}})();return entryPromise;}
function openDoc(kind){const template=document.querySelector('#'+kind+'-document');if(!template)return;returnFocus=document.activeElement;content.replaceChildren(template.content.cloneNode(true));title.textContent={resume:'Résumé',projects:'Projects',education:'Education',contact:'Contact'}[kind];document.querySelector('#download-resume').hidden=kind!=='resume';if(!dialog.open)dialog.showModal();if(kind==='resume'&&window.gsap&&!paused)gsap.fromTo('.document-shell',{y:90,scale:.88,opacity:0,rotation:-2},{y:0,scale:1,opacity:1,rotation:0,duration:.75,ease:'power3.out'});content.scrollTop=0;content.focus({preventScroll:true});}
async function revealResume(){if(window.openDeskEnvelope){await window.openDeskEnvelope();return;}const preview=document.querySelector('#envelope-preview');if(!preview||paused)return;preview.hidden=false;await new Promise(resolve=>{requestAnimationFrame(()=>preview.classList.add('is-open'));setTimeout(resolve,1400);});preview.classList.remove('is-open');preview.hidden=true;}
async function route(){const hash=window.location.hash.slice(1)||'outside';if(hash==='outside'){showOutside();return;}if(!['inside','resume','projects','education','contact'].includes(hash))return;if(!room){await enter();if(window.location.hash.slice(1)!==hash)return;}if(hash!=='resume')window.resetDeskEnvelope?.();if(hash==='inside'){if(dialog.open)dialog.close();return;}if(hash==='resume'){await revealResume();if(window.location.hash.slice(1)!==hash)return;}openDoc(hash);}
function navigate(hash){if(window.location.hash==='#'+hash)route();else window.location.hash=hash;}
window.portfolioEnter=()=>navigate('inside');document.querySelectorAll('[data-enter],#enter-door').forEach(b=>b.addEventListener('click',window.portfolioEnter));document.querySelector('#leave-hut').addEventListener('click',()=>navigate('outside'));
function closeDoc(){window.resetDeskEnvelope?.();if(dialog.open)dialog.close();navigate('inside');if(returnFocus&&returnFocus.isConnected&&!outside.contains(returnFocus))returnFocus.focus({preventScroll:true});else document.querySelector('.desk-object').focus({preventScroll:true});}
document.querySelector('#close-document').addEventListener('click',closeDoc);document.querySelector('#back-to-room').addEventListener('click',closeDoc);dialog.addEventListener('cancel',e=>{e.preventDefault();closeDoc();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDoc();}});
const lamp=document.querySelector('#lamp-switch');lamp?.addEventListener('click',()=>{const on=lamp.getAttribute('aria-pressed')!=='true';lamp.setAttribute('aria-pressed',String(on));lamp.setAttribute('aria-label',on?'Switch the desk lamp off':'Switch the desk lamp on');document.querySelector('#room-frame').classList.toggle('lamp-on',on);lamp.textContent=on?'Lamp on':'Lamp off';});
window.addEventListener('hashchange',route);window.addEventListener('pageshow',()=>{if(!transitioning)route();});route();
})();
